pub fn medians(xs: List[Int], k: Int) -> List[Float] {
  if k < 1 or k > xs.len() {
    return []
  }
  var out: List[Float] = []
  let last_start = xs.len() - k
  let mid = k / 2
  for s in range(0, last_start + 1) {
    let w = xs.slice(s, s + k).sort()
    var m = 0.0
    if k % 2 == 1 {
      m = w.get_or(mid, 0).to_float()
    } else {
      m = (w.get_or(mid - 1, 0).to_float() + w.get_or(mid, 0).to_float()) / 2.0
    }
    out = out.push(m)
  }
  return out
}
